                    f"{trial_name}: {warning} (tokens: null)"
                )
            else:
                row["total_input_tokens"] = tin
                row["total_output_tokens"] = tout
                report["patched"].append(
                    {"trial": trial_name, "input": tin, "output": tout}
                )
